  { data: { id: 'p4', label: 'Marcus Vance', type: 'person', role: 'Corporate Front Director', risk: 'MEDIUM', status: 'Under Investigation' } },
  { data: { id: 'p5', label: 'Sarah Chen', type: 'person', role: 'Financial Smurfer / Mule', risk: 'MEDIUM', status: 'Identified' } },

  // --- PHONE NODES (Blue Squares) ---
  { data: { id: 'ph1', label: '+1 (555) 019-4821 [Burner Alpha]', type: 'phone', carrier: 'T-Cell PPD', imei: '864291048201928' } },
  { data: { id: 'ph2', label: '+1 (555) 014-9982 [Burner Beta]', type: 'phone', carrier: 'Metro SIM', imei: '359182049182049' } },
  { data: { id: 'ph3', label: '+1 (555) 017-3310 [VoIP Trunk]', type: 'phone', carrier: 'SignalMesh Global', imei: 'N/A (Virtual IP)' } },
  { data: { id: 'ph4', label: '+1 (555) 012-7804 [Encrypted Sat]', type: 'phone', carrier: 'Thuraya Satellite', imei: '440182940182941' } },

  // --- ACCOUNT NODES (Green Triangles) ---
  { data: { id: 'acc1', label: 'SWIFT // CH-9804-CY [Cayman Offshore]', type: 'account', institution: 'Cayman Trust & Co', balance: '$2,450,000' } },
  { data: { id: 'acc2', label: 'USDT // 0x7f29...a81e [Tether Bridge]', type: 'account', institution: 'Tron Blockchain', balance: '$680,000 USDT' } },
  { data: { id: 'acc3', label: 'IBAN // LU-1189-99 [Apex Shell Corp]', type: 'account', institution: 'Banque Privée Lux', balance: '$1,120,000' } },
  { data: { id: 'acc4', label: 'ACH // US-Chase-4891 [Logistics Front]', type: 'account', institution: 'JPMorgan Commercial', balance: '$84,500' } },

  // --- EDGES WITH DIRECTED ARROWS ---
  { data: { id: 'e1', source: 'p1', target: 'ph1', label: 'PRIMARY DEVICE', category: 'device' } },
  { data: { id: 'e2', source: 'p2', target: 'ph2', label: 'OPERATOR', category: 'device' } },
  { data: { id: 'e3', source: 'p3', target: 'ph3', label: 'VOIP LINK', category: 'device' } },
  { data: { id: 'e4', source: 'ph1', target: 'ph2', label: '14 CALLS (42m)', category: 'comms' } },
  { data: { id: 'e5', source: 'ph2', target: 'ph3', label: 'ENCRYPTED SMS', category: 'comms' } },
  { data: { id: 'e6', source: 'p1', target: 'ph4', label: 'SAT BRIDGE', category: 'device' } },
  { data: { id: 'e7', source: 'p1', target: 'p2', label: 'TASK ORDERS', category: 'hierarchy' } },
  { data: { id: 'e8', source: 'p2', target: 'p3', label: 'COORDINATES', category: 'hierarchy' } },
  { data: { id: 'e9', source: 'p1', target: 'acc1', label: 'BENEFICIARY', category: 'financial' } },
  { data: { id: 'e10', source: 'acc1', target: 'acc2', label: 'WIRE $450,000', category: 'financial' } },
  { data: { id: 'e11', source: 'acc2', target: 'acc3', label: 'MIXER BRIDGE', category: 'financial' } },
  { data: { id: 'e12', source: 'p4', target: 'acc3', label: 'SIGNATORY', category: 'financial' } },
  { data: { id: 'e13', source: 'acc3', target: 'acc4', label: 'PAYROLL DISBURSE', category: 'financial' } },
  { data: { id: 'e14', source: 'p5', target: 'acc4', label: 'SMURF WITHDRAWAL', category: 'financial' } },
];

const FALLBACK_ALERTS = [
  {
    id: 'ALT-9041',
    severity: 'CRITICAL',
    title: 'High-Frequency Burner Ping',
    timestamp: '10 mins ago',
    targetNodeId: 'ph1',
    description: '14 consecutive short-duration burst calls detected to Burner Beta within 40 minutes.',
  },
  {
    id: 'ALT-8832',
    severity: 'CRITICAL',
    title: 'Rapid Wire Velocity & Layering',
    timestamp: '28 mins ago',
    targetNodeId: 'acc2',
    description: 'Offshore Cayman wire ($450k) immediately converted to USDT via unhosted mixer contract.',
  },
  {
    id: 'ALT-7719',
    severity: 'HIGH',
    title: 'Direct Syndicate Hierarchy Breach',
    timestamp: '1 hour ago',
    targetNodeId: 'p3',
    description: 'Enforcer Dmitri Volkov bypassed intermediary logistics to initiate encrypted sat comms.',
  },
  {
    id: 'ALT-6640',
    severity: 'MEDIUM',
    title: 'Shell Payroll Structuring',
    timestamp: '3 hours ago',
    targetNodeId: 'acc4',
    description: 'Repetitive sub-$10,000 cash deposits identified by courier Sarah Chen across 6 branch ATMs.',
  },
];

// =====================================================================
// Cytoscape Stylesheet Rules (Color, Geometry, Directed Arrows)
// =====================================================================

const CYTOSCAPE_STYLESHEET = [
  // Base Node Style
  {
    selector: 'node',
    style: {
      'label': 'data(label)',
      'color': '#cbd5e1',
      'font-size': '10px',
      'font-family': 'ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace',
      'font-weight': '600',
      'text-valign': 'bottom',
      'text-margin-y': 7,
      'text-background-color': '#090d16',
      'text-background-opacity': 0.85,
      'text-background-padding': '4px',
      'text-background-shape': 'roundrectangle',
      'border-width': 2,
      'border-color': '#475569',
      'border-opacity': 0.8,
      'width': 44,
      'height': 44,
      'transition-property': 'background-color, border-color, border-width, width, height',
      'transition-duration': '0.2s',
    },
  },
  // 1. Person nodes: Red Circles
  {
    selector: 'node[type = "person"], node[type = "Person"]',
    style: {
      'shape': 'ellipse',
      'background-color': '#ef4444',
      'border-color': '#f87171',
      'border-width': 3,
      'shadow-blur': 12,
      'shadow-color': '#ef4444',
      'shadow-opacity': 0.4,
    },
  },
  // 2. Phone nodes: Blue Squares
  {
    selector: 'node[type = "phone"], node[type = "Phone"]',
    style: {
      'shape': 'rectangle',
      'background-color': '#3b82f6',
      'border-color': '#60a5fa',
      'border-width': 3,
      'shadow-blur': 12,
      'shadow-color': '#3b82f6',
      'shadow-opacity': 0.4,
    },
  },
  // 3. Account nodes: Green Triangles
  {
    selector: 'node[type = "account"], node[type = "Account"]',
    style: {
      'shape': 'triangle',
      'background-color': '#10b981',
      'border-color': '#34d399',
      'border-width': 3,
      'shadow-blur': 12,
      'shadow-color': '#10b981',
      'shadow-opacity': 0.4,
    },
  },
  // Active / Selected Node State
  {
    selector: 'node:selected',
    style: {
      'border-width': 4,
      'border-color': '#fbbf24',
      'border-opacity': 1,
      'shadow-blur': 22,
      'shadow-color': '#fbbf24',
      'shadow-opacity': 0.9,
      'width': 50,
      'height': 50,
    },
  },
  // Highlighted Target Node (e.g. from Alert click)
  {
    selector: 'node.highlighted',
    style: {
      'border-width': 4,
      'border-color': '#f59e0b',
      'shadow-blur': 30,
      'shadow-color': '#f59e0b',
      'shadow-opacity': 1,
    },
  },
  // Base Edge Style: Directed Arrows
  {
    selector: 'edge',
    style: {
      'width': 2,
      'line-color': '#475569',
      'target-arrow-shape': 'triangle',
      'target-arrow-color': '#94a3b8',
      'arrow-scale': 1.25,
      'curve-style': 'bezier',
      'label': 'data(label)',
      'font-size': '9px',
      'font-family': 'ui-monospace, monospace',
      'color': '#94a3b8',
      'text-background-color': '#020617',
      'text-background-opacity': 0.85,
      'text-background-padding': '3px',
      'text-rotation': 'autorotate',
      'opacity': 0.75,
    },
  },
  // Edge Selected / Highlighted
  {
    selector: 'edge:selected',
    style: {
      'width': 3.5,
      'line-color': '#fbbf24',
      'target-arrow-color': '#fbbf24',
      'opacity': 1,
    },
  },
];

// =====================================================================
// Main Component
// =====================================================================

export default function CriminalNetworkDashboard() {
  const [elements, setElements] = useState([]);
  const [alerts, setAlerts] = useState([]);
  const [selectedNode, setSelectedNode] = useState(null);
  const [loading, setLoading] = useState(true);
  const [isFallbackMode, setIsFallbackMode] = useState(false);
  const [typeFilter, setTypeFilter] = useState('all');

  const cyRef = useRef(null);

  // -------------------------------------------------------------------
  // Cytoscape Compound Spring Embedder (cose) Layout Configuration
  // -------------------------------------------------------------------
  const layout = useMemo(
    () => ({
      name: 'cose',
      animate: true,
      animationDuration: 750,
      fit: true,
      padding: 50,
      randomize: false,
      nodeRepulsion: 12000,
      idealEdgeLength: 120,
      edgeElasticity: 0.35,
      nestingFactor: 1.2,
      gravity: 0.3,
      numIter: 1000,
      initialTemp: 200,
      coolingFactor: 0.95,
      minTemp: 1.0,
    }),
    []
  );

  // -------------------------------------------------------------------
  // Data Fetching with Graceful Offline Fallback
  // -------------------------------------------------------------------
  useEffect(() => {
    let isMounted = true;

    async function fetchIntelligenceData() {
      setLoading(true);
      let networkData = null;
      let anomaliesData = null;

      // 1. Fetch Graph Network
      try {
        const res = await fetch('http://localhost:8000/api/network', {
          headers: { 'Accept': 'application/json' },
        });
        if (!res.ok) throw new Error(`HTTP status ${res.status}`);
        networkData = await res.json();
      } catch (err) {
        console.info('Live network endpoint unreachable. Activating simulated intelligence fallback.', err.message);
      }

      // 2. Fetch Anomalies
      try {
        const res = await fetch('/api/anomalies', {
          headers: { 'Accept': 'application/json' },
        });
        if (!res.ok) throw new Error(`HTTP status ${res.status}`);
        anomaliesData = await res.json();
      } catch (err) {
        console.info('Live anomaly endpoint unreachable. Activating simulated alert fallback.', err.message);
      }

      if (isMounted) {
        if (networkData && (Array.isArray(networkData) || networkData.elements)) {
          setElements(networkData.elements || networkData);
          setIsFallbackMode(false);
        } else {
          setElements(FALLBACK_GRAPH_ELEMENTS);
          setIsFallbackMode(true);
        }

        if (anomaliesData && Array.isArray(anomaliesData)) {
          setAlerts(anomaliesData);
        } else {
          setAlerts(FALLBACK_ALERTS);
        }

        setLoading(false);
      }
    }

    fetchIntelligenceData();
    return () => {
      isMounted = false;
    };
  }, []);

  // -------------------------------------------------------------------
  // Setup Cytoscape Event Handlers
  // -------------------------------------------------------------------
  const handleCyInit = (cy) => {
    cyRef.current = cy;

    // Remove old listeners to prevent leak on hot reload
    cy.unbind('tap');

    // Click on Node -> Show Properties Panel
    cy.on('tap', 'node', (evt) => {
      const node = evt.target;
      const data = node.data();
      setSelectedNode(data);
    });

    // Click on Canvas Background -> Clear Selection
    cy.on('tap', (evt) => {
      if (evt.target === cy) {
        setSelectedNode(null);
      }
    });
  };

  // -------------------------------------------------------------------
  // Interactive Helper: Focus Graph on an Alert's Target Node
  // -------------------------------------------------------------------
  const handleSelectAlert = (targetNodeId) => {
    if (!cyRef.current) return;
    const cy = cyRef.current;
    const node = cy.getElementById(targetNodeId);

    if (node && node.length > 0) {
      cy.elements().removeClass('highlighted');
      node.addClass('highlighted');
      cy.animate({
        center: { eles: node },
        zoom: 1.6,
        duration: 500,
      });
      setSelectedNode(node.data());
    }
  };

  // -------------------------------------------------------------------
  // Layout and Viewport Controls
  // -------------------------------------------------------------------
  const handleResetLayout = () => {
    if (cyRef.current) {
      const cy = cyRef.current;
      cy.elements().removeClass('highlighted');
      const coseLayout = cy.layout(layout);
      coseLayout.run();
    }
  };

  const handleFitGraph = () => {
    if (cyRef.current) {
      cyRef.current.animate({ fit: { padding: 40 }, duration: 400 });
    }
  };

  // Filter elements based on selection dropdown
  const filteredElements = useMemo(() => {
    if (typeFilter === 'all') return elements;
    return elements.filter((el) => {
      if (el.data.source && el.data.target) return true; // keep edges
      return el.data.type?.toLowerCase() === typeFilter.toLowerCase();
    });
  }, [elements, typeFilter]);

  return (
    <div className="flex h-screen w-screen flex-col bg-slate-950 text-slate-100 font-sans overflow-hidden antialiased">
      {/* --------------------------------------------------------------- */}
      {/* TOP STATUS BAR                                                  */}
      {/* --------------------------------------------------------------- */}
      <header className="flex h-14 shrink-0 items-center justify-between border-b border-slate-800/80 bg-slate-900/90 px-5 backdrop-blur-md z-20 shadow-md">
        <div className="flex items-center space-x-3">
          <div className="flex h-8 w-8 items-center justify-center rounded-md bg-red-600/20 border border-red-500/40 text-red-400 font-mono font-bold text-xs tracking-wider">
            LEO
          </div>
          <div>
            <h1 className="text-sm font-semibold tracking-wide text-slate-100 uppercase font-mono">
              Sentinel Intel Nexus <span className="text-slate-500">//</span> Criminal Network Analyzer
            </h1>
            <p className="text-[10px] text-slate-400 font-mono">
              CYTOSCAPE GRAPH SYSTEM &bull; LAW ENFORCEMENT INTELLIGENCE v2.4
            </p>
          </div>
        </div>

        {/* Global Metadata & Controls */}
        <div className="flex items-center space-x-4 text-xs font-mono">
          <div className="flex items-center space-x-2 rounded-full border border-slate-800 bg-slate-950/60 px-3 py-1">
            <span
              className={`h-2 w-2 rounded-full ${
                isFallbackMode ? 'bg-amber-400 animate-pulse' : 'bg-emerald-400 animate-ping'
              }`}
            />
            <span className="text-slate-300">
              {isFallbackMode ? 'API OFFLINE (SIMULATED DATA)' : 'LIVE STREAM ACTIVE'}
            </span>
          </div>

          <div className="flex items-center space-x-1 border-l border-slate-800 pl-4">
            <span className="text-slate-400">TYPE FILTER:</span>
            <select
              value={typeFilter}
              onChange={(e) => setTypeFilter(e.target.value)}
              className="rounded border border-slate-700 bg-slate-800/90 px-2 py-0.5 text-xs text-slate-200 outline-none focus:border-blue-500"
            >
              <option value="all">ALL NODES</option>
              <option value="person">PERSONS (RED)</option>
              <option value="phone">PHONES (BLUE)</option>
              <option value="account">ACCOUNTS (GREEN)</option>
            </select>
          </div>

          <button
            onClick={handleFitGraph}
            className="rounded border border-slate-700 bg-slate-800/80 px-2.5 py-1 text-slate-300 hover:bg-slate-700 hover:text-white transition"
            title="Fit network to canvas"
          >
            FIT
          </button>
          <button
            onClick={handleResetLayout}
            className="rounded border border-blue-600/40 bg-blue-600/20 px-2.5 py-1 text-blue-300 hover:bg-blue-600/30 transition"
            title="Re-run COSE Physics Engine"
          >
            RE-LAYOUT
          </button>
        </div>
      </header>

      {/* --------------------------------------------------------------- */}
      {/* MAIN CONTENT AREA                                               */}
      {/* --------------------------------------------------------------- */}
      <div className="relative flex flex-1 overflow-hidden">
        {/* ============================================================= */}
        {/* LEFT SIDEBAR: ALERTS & ANOMALIES                              */}
        {/* ============================================================= */}
        <aside className="flex w-84 shrink-0 flex-col border-r border-slate-800/80 bg-slate-900/60 backdrop-blur-sm z-10">
          <div className="flex items-center justify-between border-b border-slate-800/80 px-4 py-3 bg-slate-900/90">
            <div className="flex items-center space-x-2">
              <span className="flex h-2 w-2 rounded-full bg-red-500 animate-pulse" />
              <h2 className="text-xs font-bold tracking-wider text-slate-200 uppercase font-mono">
                Active Anomalies ({alerts.length})
              </h2>
            </div>
            <span className="text-[10px] text-slate-400 font-mono">LIVE FEED</span>
          </div>

          <div className="flex-1 overflow-y-auto p-3 space-y-2.5 scrollbar-thin scrollbar-thumb-slate-700">
            {alerts.length === 0 && !loading && (
              <div className="py-8 text-center text-xs text-slate-500 font-mono">
                No active syndicate alerts detected.
              </div>
            )}

            {alerts.map((alert) => {
              const isCrit = alert.severity === 'CRITICAL';
              const isHigh = alert.severity === 'HIGH';
              return (
                <div
                  key={alert.id}
                  onClick={() => handleSelectAlert(alert.targetNodeId)}
                  className={`group relative cursor-pointer rounded-lg border p-3 transition-all hover:translate-x-1 ${
                    isCrit
                      ? 'border-red-800/40 bg-red-950/20 hover:border-red-500 hover:bg-red-950/40'
                      : isHigh
                      ? 'border-amber-800/40 bg-amber-950/20 hover:border-amber-500 hover:bg-amber-950/40'
                      : 'border-slate-800 bg-slate-950/40 hover:border-slate-600 hover:bg-slate-900/60'
                  }`}
                >
                  <div className="flex items-center justify-between mb-1">
                    <span
                      className={`text-[9px] font-bold font-mono px-1.5 py-0.5 rounded uppercase tracking-wider ${
                        isCrit
                          ? 'bg-red-500/20 text-red-400 border border-red-500/40'
                          : isHigh
                          ? 'bg-amber-500/20 text-amber-400 border border-amber-500/40'
                          : 'bg-slate-700 text-slate-300'
                      }`}
                    >
                      {alert.severity}
                    </span>
                    <span className="text-[10px] text-slate-400 font-mono">{alert.timestamp}</span>
                  </div>

                  <h3 className="text-xs font-semibold text-slate-200 group-hover:text-white mb-1">
                    {alert.title}
                  </h3>

                  <p className="text-[11px] leading-relaxed text-slate-400 line-clamp-2">
                    {alert.description}
                  </p>

                  <div className="mt-2 flex items-center justify-between border-t border-slate-800/60 pt-2 text-[10px] font-mono text-slate-400">
                    <span>TARGET: {alert.targetNodeId}</span>
                    <span className="text-blue-400 group-hover:underline">FOCUS IN GRAPH &rarr;</span>
                  </div>
                </div>
              );
            })}
          </div>

          {/* Sidebar Legend Footer */}
          <div className="border-t border-slate-800/80 bg-slate-950/70 p-3.5 text-xs font-mono">
            <div className="text-[10px] font-semibold text-slate-400 uppercase tracking-wider mb-2">
              Entity Type Legend
            </div>
            <div className="space-y-1.5 text-[11px]">
              <div className="flex items-center space-x-2">
                <span className="h-3 w-3 rounded-full bg-red-500 shadow-[0_0_8px_#ef4444]" />
                <span className="text-slate-300">Person (Target / Suspect)</span>
              </div>
              <div className="flex items-center space-x-2">
                <span className="h-3 w-3 rounded-sm bg-blue-500 shadow-[0_0_8px_#3b82f6]" />
                <span className="text-slate-300">Phone (Device / Burner / VoIP)</span>
              </div>
              <div className="flex items-center space-x-2">
                <span
                  className="h-0 w-0 border-x-4 border-x-transparent border-b-[8px] border-b-emerald-500"
                  style={{ display: 'inline-block' }}
                />
                <span className="text-slate-300">Account (SWIFT / Crypto / IBAN)</span>
              </div>
            </div>
          </div>
        </aside>

        {/* ============================================================= */}
        {/* MAIN CENTRAL GRAPH AREA                                       */}
        {/* ============================================================= */}
        <main className="relative flex-1 bg-slate-950 bg-[radial-gradient(#1e293b_1px,transparent_1px)] [background-size:24px_24px]">
          {loading ? (
            <div className="absolute inset-0 flex flex-col items-center justify-center bg-slate-950/80 z-20">
              <div className="h-10 w-10 animate-spin rounded-full border-2 border-red-500 border-t-transparent mb-3" />
              <p className="font-mono text-xs tracking-wider text-slate-300 uppercase">
                Synchronizing Syndicate Topology...
              </p>
            </div>
          ) : (
            <CytoscapeComponent
              elements={filteredElements}
              stylesheet={CYTOSCAPE_STYLESHEET}
              layout={layout}
              cy={handleCyInit}
              className="h-full w-full"
              wheelSensitivity={0.25}
              minZoom={0.2}
              maxZoom={3.5}
            />
          )}

          {/* Quick HUD Overlay */}
          <div className="pointer-events-none absolute bottom-4 left-4 rounded-md border border-slate-800 bg-slate-900/80 px-3 py-2 text-[11px] font-mono text-slate-400 backdrop-blur">
            <div>TOTAL NODES: {elements.filter((e) => !e.data.source).length}</div>
            <div>LINKED EDGES: {elements.filter((e) => e.data.source).length}</div>
            <div className="text-[10px] text-slate-500 mt-1">CLICK NODE TO INSPECT PROPERTIES</div>
          </div>

          {/* =========================================================== */}
          {/* FLOATING PROPERTIES PANEL (Displayed on Node Click)         */}
          {/* =========================================================== */}
          {selectedNode && (
            <div className="absolute top-4 right-4 w-80 rounded-xl border border-slate-700/80 bg-slate-900/95 p-4 shadow-2xl backdrop-blur-md z-30 transition-all duration-200">
              <div className="flex items-start justify-between border-b border-slate-800 pb-2 mb-3">
                <div className="flex items-center space-x-2">
                  <span
                    className={`h-3 w-3 ${
                      selectedNode.type === 'person'
                        ? 'rounded-full bg-red-500'
                        : selectedNode.type === 'phone'
                        ? 'rounded-sm bg-blue-500'
                        : 'rounded-none rotate-45 bg-emerald-500'
                    }`}
                  />
                  <div>
                    <h4 className="text-xs font-bold uppercase tracking-wider text-slate-200 font-mono">
                      Entity Dossier
                    </h4>
                    <span className="text-[10px] text-slate-400 font-mono">ID: {selectedNode.id}</span>
                  </div>
                </div>
                <button
                  onClick={() => setSelectedNode(null)}
                  className="rounded p-1 text-slate-400 hover:bg-slate-800 hover:text-white transition"
                  title="Close Inspector"
                >
                  &times;
                </button>
              </div>

              {/* Core Properties as required */}
              <div className="space-y-2 text-xs font-mono">
                <div className="rounded bg-slate-950/70 p-2 border border-slate-800">
                  <span className="text-[10px] text-slate-400 uppercase block">Label / Designation</span>
                  <span className="text-sm font-semibold text-slate-100">{selectedNode.label}</span>
                </div>

                <div className="grid grid-cols-2 gap-2">
                  <div className="rounded bg-slate-950/70 p-2 border border-slate-800">
                    <span className="text-[10px] text-slate-400 uppercase block">Entity Type</span>
                    <span
                      className={`font-bold uppercase ${
                        selectedNode.type === 'person'
                          ? 'text-red-400'
                          : selectedNode.type === 'phone'
                          ? 'text-blue-400'
                          : 'text-emerald-400'
                      }`}
                    >
                      {selectedNode.type}
                    </span>
                  </div>
                  <div className="rounded bg-slate-950/70 p-2 border border-slate-800">
                    <span className="text-[10px] text-slate-400 uppercase block">System Status</span>
                    <span className="text-slate-200">{selectedNode.status || 'Active Surveillance'}</span>
                  </div>
                </div>

                {/* Additional Intelligence Metadata */}
                {selectedNode.role && (
                  <div className="rounded bg-slate-950/70 p-2 border border-slate-800">
                    <span className="text-[10px] text-slate-400 uppercase block">Syndicate Role</span>
                    <span className="text-amber-300 font-semibold">{selectedNode.role}</span>
                  </div>
                )}

                {selectedNode.carrier && (
                  <div className="rounded bg-slate-950/70 p-2 border border-slate-800">
                    <span className="text-[10px] text-slate-400 uppercase block">Telecom Carrier</span>
                    <span className="text-slate-300">{selectedNode.carrier}</span>
                  </div>
                )}

                {selectedNode.balance && (
                  <div className="rounded bg-slate-950/70 p-2 border border-slate-800">
                    <span className="text-[10px] text-slate-400 uppercase block">Estimated Liquid Assets</span>
                    <span className="text-emerald-400 font-bold">{selectedNode.balance}</span>
                  </div>
                )}

                {selectedNode.risk && (
                  <div className="flex items-center justify-between rounded bg-red-950/30 border border-red-800/40 p-2">
                    <span className="text-[10px] text-red-400 uppercase font-bold">Threat Evaluation</span>
                    <span className="text-xs font-bold text-red-400">{selectedNode.risk}</span>
                  </div>
                )}
              </div>

              {/* Action Buttons */}
              <div className="mt-3.5 flex space-x-2 pt-2 border-t border-slate-800">
                <button
                  onClick={() => handleSelectAlert(selectedNode.id)}
                  className="flex-1 rounded bg-blue-600/20 border border-blue-500/40 py-1.5 text-center text-[11px] font-mono text-blue-300 hover:bg-blue-600/30 transition"
                >
                  CENTER NODE
                </button>
                <button
                  onClick={() => setSelectedNode(null)}
                  className="rounded border border-slate-700 bg-slate-800 px-3 py-1.5 text-[11px] font-mono text-slate-300 hover:bg-slate-700 transition"
                >
                  DISMISS
                </button>
              </div>
            </div>
          )}
        </main>
      </div>
    </div>
  );
}
